    {
      "card_ids": ["C19"],
      "claim": "Thalidomide absolute bioavailability in fasting healthy volunteers was probably high at 80–100% at low doses, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved condition-matched absolute bioavailability values are well above the 20% threshold, with fasted-state numeric estimates ranging from about 40% to 100%. The strongest evidence therefore supports high oral bioavailability.",
  "evidence_gaps": [
    "No retrieved record reports an absolute oral bioavailability below 20%.",
    "Some records are qualitative or not explicitly fasted, but the strongest condition-matched records are numeric and fasted."
  ],
